package com.lianxibu.site.service.content;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.lianxibu.site.service.content.ReportInputFixtures.*;
import com.lianxibu.site.service.identity.IdentityService.Actor;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;

class ReportInputSummaryReadServiceTest {
 private final Actor owner=new Actor("fictional-owner","owner");
 private ReportInputSummaryReadService service(ObjectNode root){return new ReportInputSummaryReadService((r,s)->proof(r,s,root),key());}
 @Test void completeFrozenGroupsRealPaginationAndNullsRemainImmutable(){var service=service(root("daily",51));var first=service.read(owner,"fictional-report","fictional-snapshot",null,20);assertEquals(51L,first.get("total"));assertEquals(4,((List<?>)first.get("group_counts")).size());var items=(List<Map<String,Object>>)first.get("items");assertEquals("fictional-member-000",items.getFirst().get("member_id"));assertNull(items.getFirst().get("revision"));assertThrows(UnsupportedOperationException.class,()->items.getFirst().put("title","fictional alteration"));assertThrows(UnsupportedOperationException.class,()->first.put("total",0));assertFalse(first.toString().contains("internal body"));String cursor=(String)first.get("next_cursor");assertTrue(cursor.length()<=512);var second=service.read(owner,"fictional-report","fictional-snapshot",cursor,20);assertEquals("fictional-member-020",((List<Map<String,Object>>)second.get("items")).getFirst().get("member_id"));var third=service.read(owner,"fictional-report","fictional-snapshot",(String)second.get("next_cursor"),20);assertEquals(11,((List<?>)third.get("items")).size());assertNull(third.get("next_cursor"));}
 @Test void weeklyMonthlyAndKnownZeroUseCanonicalShanghaiPeriods(){for(String type:List.of("weekly","monthly")){var page=service(root(type,0)).read(owner,"fictional-report","fictional-snapshot",null,20);assertEquals(type,page.get("report_type"));assertEquals(1,((List<?>)page.get("group_counts")).size());assertEquals(0L,page.get("total"));assertNull(page.get("next_cursor"));}var page=service(root("daily",0)).read(owner,"fictional-report","fictional-snapshot",null,20);assertEquals(4,((List<?>)page.get("group_counts")).size());}
 @Test void heatProofAndExcludedMembersAreValidatedAcrossFullSet(){var root=root("daily",0);var profile=(ObjectNode)root.get("report_summary_v1");var members=profile.withArray("members");for(int i=0;i<2;i++){var item=member(i,"historical_heat",true);item.put("occurrence_count",10-i);item.put("rank",i+1);members.add(item);}members.add(member(2,"historical_heat",false));profile.put("total",3);((ObjectNode)profile.withArray("group_counts").get(2)).put("included_count",2).put("excluded_count",1);var page=service(root).read(owner,"fictional-report","fictional-snapshot",null,1);assertEquals(3L,page.get("total"));var corrupt=root.deepCopy();((ObjectNode)corrupt.get("report_summary_v1").get("members").get(1)).put("rank",1);ObjectNode duplicateRank=corrupt;assertThrows(IllegalStateException.class,()->service(duplicateRank).read(owner,"fictional-report","fictional-snapshot",null,1));corrupt=root.deepCopy();((ObjectNode)corrupt.get("report_summary_v1").get("members").get(0)).put("occurrence_count",1);ObjectNode reversed=corrupt;assertThrows(IllegalStateException.class,()->service(reversed).read(owner,"fictional-report","fictional-snapshot",null,1));}
 @Test void cursorIsAuthenticatedAndBindsEveryScopeIncludingChangedProof(){var value=new AtomicReference<>(root("daily",3));var service=new ReportInputSummaryReadService((r,s)->proof(r,s,value.get()),key());String cursor=(String)service.read(owner,"fictional-report","fictional-snapshot",null,1).get("next_cursor");for(String[] args:List.of(new String[]{"fictional-other","fictional-snapshot","1"},new String[]{"fictional-report","fictional-other","1"},new String[]{"fictional-report","fictional-snapshot","2"}))assertThrows(ReportInputSummaryReadService.CursorConflict.class,()->service.read(owner,args[0],args[1],cursor,Integer.parseInt(args[2])));String tampered=(cursor.startsWith("A")?"B":"A")+cursor.substring(1);assertThrows(IllegalArgumentException.class,()->service.read(owner,"fictional-report","fictional-snapshot",tampered,1));value.get().put("generation",3);assertThrows(ReportInputSummaryReadService.CursorConflict.class,()->service.read(owner,"fictional-report","fictional-snapshot",cursor,1));}
 @Test void ownerAndInvalidQueryNeverTouchStore(){var store=mock(ReportInputSummaryReadService.Store.class);var service=new ReportInputSummaryReadService(store,key());assertThrows(ReportInputSummaryReadService.Denied.class,()->service.read(new Actor("fictional-user","user"),"fictional-report","fictional-snapshot",null,20));assertThrows(IllegalArgumentException.class,()->service.read(owner,"fictional-report","fictional-snapshot\n",null,20));assertThrows(IllegalArgumentException.class,()->service.read(owner,"fictional-report","fictional-snapshot",null,51));verifyNoInteractions(store);}
 @Test void legacyReasonsAreExplicitAndNeverFabricateFields(){for(var reason:ReportInputSummaryReadService.LegacyReason.values()){var service=new ReportInputSummaryReadService((r,s)->new ReportInputSummaryReadService.Proof(r,reason==ReportInputSummaryReadService.LegacyReason.UNPROVEN_REPORT_LINK?null:s,null,reason),key());var page=service.read(owner,"fictional-report","fictional-snapshot",null,20);assertEquals(Set.of("report_id","input_snapshot_id","state","reason"),page.keySet());assertEquals(reason.name().toLowerCase(Locale.ROOT),page.get("reason"));assertThrows(IllegalArgumentException.class,()->service.read(owner,"fictional-report","fictional-snapshot","fictional-cursor",20));}var legacy=root("daily",1);legacy.remove("report_summary_v1");legacy.put("generation",0);assertEquals("unproven_group_manifest",service(legacy).read(owner,"fictional-report","fictional-snapshot",null,20).get("reason"));}
 @Test void associationUnknownAndHashFailuresRemainDistinct(){var store=mock(ReportInputSummaryReadService.Store.class);var service=new ReportInputSummaryReadService(store,key());assertThrows(ReportInputSummaryReadService.Missing.class,()->service.read(owner,"fictional-report","fictional-snapshot",null,20));when(store.snapshot(anyString(),anyString())).thenReturn(proof("fictional-report","fictional-new",root("daily",1)));assertThrows(ReportInputSummaryReadService.SnapshotConflict.class,()->service.read(owner,"fictional-report","fictional-snapshot",null,20));when(store.snapshot(anyString(),anyString())).thenReturn(new ReportInputSummaryReadService.Proof("fictional-report","fictional-snapshot",new ReportInputSummaryReadService.Snapshot("fictional-snapshot","b".repeat(64),root("daily",1).toString()),null));assertThrows(IllegalStateException.class,()->service.read(owner,"fictional-report","fictional-snapshot",null,20));}
 @Test void badFullManifestCannotHideOutsideRequestedPage(){for(int mode=0;mode<8;mode++){var root=root("daily",3);var profile=(ObjectNode)root.get("report_summary_v1");var last=(ObjectNode)profile.get("members").get(2);switch(mode){case 0->last.put("member_id","fictional-member-001");case 1->last.put("material_hash","a".repeat(64)+"\n");case 2->last.put("request_json","Fictional forbidden field");case 3->profile.put("total",4);case 4->profile.put("period_start","2026-01-05T00:00:00.000000Z");case 5->profile.put("timezone","UTC");case 6->last.put("included",false);case 7->root.put("cutoff","2026-01-04T01:00:00Z");}assertThrows(IllegalStateException.class,()->service(root).read(owner,"fictional-report","fictional-snapshot",null,1));}}

 @Test void completeIdentityAndMalformedCutoffCannotBecomeUnavailableSuccess(){var root=root("daily",2);var profile=(ObjectNode)root.get("report_summary_v1");var members=profile.withArray("members");var duplicate=((ObjectNode)members.get(0)).deepCopy();duplicate.put("member_id","fictional-distinct-display-id");members.set(1,duplicate);assertThrows(IllegalStateException.class,()->service(root).read(owner,"fictional-report","fictional-snapshot",null,1));var corrupt=root("daily",1);corrupt.put("cutoff","fictional-bad-time");assertThrows(IllegalStateException.class,()->service(corrupt).read(owner,"fictional-report","fictional-snapshot",null,20));var legacy=root("daily",0);legacy.remove("report_summary_v1");assertThrows(IllegalArgumentException.class,()->service(legacy).read(owner,"fictional-report","fictional-snapshot","fictional-cursor",20));}
 @Test void heatTieUsesFrozenResourceIdentityAndPageOrderUsesUtf8(){var root=root("daily",0);var profile=(ObjectNode)root.get("report_summary_v1");var members=profile.withArray("members");for(int i=0;i<2;i++){var item=member(i,"historical_heat",true);item.put("member_id",i==0?"fictional-😀":"fictional-\uE000");item.put("occurrence_count",10);item.put("rank",i+1);members.add(item);}profile.put("total",2);((ObjectNode)profile.get("group_counts").get(2)).put("included_count",2);var page=service(root).read(owner,"fictional-report","fictional-snapshot",null,20);assertEquals("fictional-\uE000",((List<Map<String,Object>>)page.get("items")).getFirst().get("member_id"));((ObjectNode)members.get(1)).put("rank",1);assertThrows(IllegalStateException.class,()->service(root).read(owner,"fictional-report","fictional-snapshot",null,20));}
}
